// The commands' permissions (permissions/autogenerated) and the schema of
// permissions/default.toml, generated by tauri-plugin as every Tauri
// plugin does. Keep the list equal to `COMMANDS` in src/lib.rs.
const COMMANDS: &[&str] = &["open", "save", "export", "library_fetch", "validate"];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).build();
}
